def svg(name: str, size: int = 18, stroke: float = 2.0, cls: str = "") -> str:
    inner = ICONS.get(name, "")
    if not inner:
        return ""
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" viewBox="0 0 24 24" '
        f'fill="none" stroke="currentColor" stroke-width="{stroke}" stroke-linecap="round" '
        f'stroke-linejoin="round" class="fdc-svg {cls}" aria-hidden="true">{inner}</svg>'
    )


def _svg_source(name: str, color: str) -> str:
    inner = ICONS.get(name, "")
    if not inner:
        return ""
    return (
        '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" '
        f'fill="none" stroke="{color}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">{inner}</svg>'
    )


def mask_uri(name: str) -> str:
    """Ícone preto usado como máscara CSS; a cor vem do currentColor do elemento."""
    source = _svg_source(name, "#000")
    if not source:
        return "none"
    return 'url("data:image/svg+xml;utf8,' + quote(source, safe="/:=;,()") + '")'


def color_uri(name: str, color: str) -> str:
    source = _svg_source(name, color)
    if not source:
        return ""
    return 'url("data:image/svg+xml;utf8,' + quote(source, safe="/:=;,()") + '")'
